if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function;out=fullfile(workspace,'derivatives','function_stage3_network_20261017');if isfolder(out),error('cog:Exists','Preserve output');end;mkdir(out);subjects=["100206";"100307";"100408"];manifest=table;matrices=[];
