    source=fullfile(workspace,'derivatives','function_stage1_real_20261016','timeseries_results',subjects(k),'REST1_LR_prefix256','static_fc.mat');s=load(source,'fc');nodeIds="roi"+string((1:size(s.fc.correlation,1))');data=struct('matrix',s.fc.correlation,'nodeIds',nodeIds,'source',source);file=fullfile(out,subjects(k)+"_network.mat");save(file,'data');manifest=[manifest;table(subjects(k),"","REST1_LR_prefix256",string(file),'VariableNames',{'subject','session','run','data_file'})];z=s.fc.fisherZ;z(1:size(z,1)+1:end)=0;matrices(:,:,k)=z; %#ok<AGROW>
end
data=struct('matrices',matrices,'nodeIds',nodeIds,'independentUnitIds',subjects);file=fullfile(out,'nbs_input.mat');save(file,'data');cfg=network_config;cfg.manifestFile=fullfile(out,'runs.tsv');writetable(manifest,cfg.manifestFile,'FileType','text','Delimiter','\t');cfg.outputRoot=fullfile(out,'results');cfg.bctPath='D:/matlab/atoolbox/BCT_function_20261017/2019_03_03_BCT';cfg.execute=true;cfg.options.negativePolicy='drop';cfg.options.densities=[.2 .4 .6 .8];cfg.options.communityRepeats=10;cfg.options.nNull=9;cfg.nbsDataFile=file;cfg.nbs.threshold=2;cfg.nbs.exchangeabilityNote='Engineering only: 3 subject rows; family dependence and sign symmetry not established. Exact enumeration demonstrates code, not scientific inference.';summary=run_network(cfg);summary.scope='3 existing REST256 six-node FC matrices, positive-weight community/density sensitivity and binary degree nulls; exact8-sign one-sample Fisher-z NBS, threshold2/both/extent. Tiny/dense null mixing and population inference not established.';summary.skipped='General nuisance/two-sample NBS and spatially constrained/strength-preserving nulls are outside this baseline. Prior Moran/spin interfaces remain separate.';cog.write_json(fullfile(out,'VALIDATION.json'),summary);
